from pathlib import Path
p = Path('web/src/lib/space-display.ts')
s = p.read_text()
old = '''export const getDuplicateSpaceTitles = (spaces: readonly { title: string }[]): ReadonlySet<string> => {
  const seen = new Set<string>();
  const duplicates = new Set<string>();

  for (const space of spaces) {
    if (seen.has(space.title)) {
      duplicates.add(space.title);
    } else {
      seen.add(space.title);
    }
  }

  return duplicates;
};
'''
new = '''export const getDuplicateSpaceTitles = (spaces: readonly { title: string }[]): ReadonlySet<string> => {
  const counts = new Map<string, number>();
  const originalsByNormalizedTitle = new Map<string, Set<string>>();

  for (const space of spaces) {
    const normalizedTitle = space.title.normalize(\"NFC\");
    counts.set(normalizedTitle, (counts.get(normalizedTitle) ?? 0) + 1);

    let originals = originalsByNormalizedTitle.get(normalizedTitle);
    if ("'!originals) {
      originals = new Set<string>();
      originalsByNormalizedTitle.set(normalizedTitle, originals);
    }
    originals.add(space.title);
  }

  const duplicates = new Set<string>();
  for (const space of spaces) {
    const normalizedTitle = space.title.normalize("NFC");
    if ((counts.get(normalizedTitle) ?? 0) >= 2) {
      duplicates.add(space.title);
    }
  }

  return duplicates;
};
'"'''
if old not in s:
    raise SystemExit('expected function not found')
p.write_text(s.replace(old, new))
